sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 offset;
uniform float scale;
uniform float brightness;
uniform float darkMatter;
float hash12(float2 p) {
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
float2 hash22(float2 p) {
    float3 q = fract(float3(p.xyx) * float3(0.1031, 0.1030, 0.0973));
    q += dot(q, q.yzx + 33.33);
    return fract((q.xx + q.yz) * q.zy);
}
float hash13(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}
float vnoise(float3 p) {
    float3 i = floor(p);
    float3 f = fract(p);
    f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    float a = mix(hash13(i), hash13(i + float3(1, 0, 0)), f.x);
    float b = mix(hash13(i + float3(0, 1, 0)), hash13(i + float3(1, 1, 0)), f.x);
    float c = mix(hash13(i + float3(0, 0, 1)), hash13(i + float3(1, 0, 1)), f.x);
    float d = mix(hash13(i + float3(0, 1, 1)), hash13(i + float3(1, 1, 1)), f.x);
    return mix(mix(a, b, f.y), mix(c, d, f.y), f.z);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float2 c = size * 0.5;
    float zoom = max(scale, 0.01) / 0.3;
    float3 rgb = float3(0.012, 0.02, 0.04);
    float gain = brightness / 0.015;
    for (int k = 0; k < 7; k++) {
        float depth = 1.0 + float(k) * 0.55;
        float cellSize = 46.0 / pow(zoom, 0.25) * depth / (1.0 + 0.15 * float(k));
        float2 q = (coord - c + offset / depth) / cellSize;
        float2 n = floor(q);
        float2 h = hash22(n + float(k) * 31.7);
        float2 starAt = n + 0.15 + 0.7 * h;
        float d = length((q - starAt) * cellSize);
        float b = hash12(n * 1.31 + float(k) * 7.9);
        float lit = step(0.55, b) * pow(b, 6.0);
        float core = exp(-d * d / (0.9 + 1.6 * b * b));
        float halo = exp(-d / (1.6 + 2.0 * b)) * 0.25;
        float3 tint = mix(float3(0.75, 0.85, 1.0), mix(float3(1.0, 0.7, 0.95), float3(0.7, 1.0, 0.95), h.y), h.x * 0.6);
        float dust = vnoise(float3((coord - c + offset / depth) / (220.0 / zoom), float(k) * 3.1));
        float veil = mix(1.0, smoothstep(0.25, 0.75, dust), clamp(darkMatter, 0.0, 1.0));
        rgb += tint * lit * (core + halo) * veil * gain * 1.6 / depth;
        rgb += float3(0.03, 0.035, 0.07) * dust * max(darkMatter - 0.5, 0.0) * 0.4;
    }
    rgb = 1.0 - exp(-rgb * 1.6);
    return half4(half3(rgb) * src.a, src.a);
}
